1	export type Cell = [x: number, y: number];
2	
3	const NEIGHBOR_OFFSETS: ReadonlyArray<Cell> = [
4	  [-1, -1], [-1, 0], [-1, 1],
5	  [ 0, -1],          [ 0, 1],
6	  [ 1, -1], [ 1, 0], [ 1, 1],
7	];
8	
9	const cellKey = ([x, y]: Cell): string => `${x},${y}`;
10	
11	const willBeAlive = (isAlive: boolean, neighbors: number): boolean =>
12	  neighbors === 3 || (isAlive && neighbors === 2);
13	
14	const neighborsOf = ([x, y]: Cell): Cell[] =>
15	  NEIGHBOR_OFFSETS.map(([dx, dy]) => [x + dx, y + dy]);
16	
17	export function nextGeneration(liveCells: Cell[]): Cell[] {
18	  const alive = new Set(liveCells.map(cellKey));
19	  const neighborCounts = new Map<string, { cell: Cell; count: number }>();
20	
21	  for (const cell of liveCells) {
22	    for (const neighbor of neighborsOf(cell)) {
23	      const key = cellKey(neighbor);
24	      const prior = neighborCounts.get(key)?.count ?? 0;
25	      neighborCounts.set(key, { cell: neighbor, count: prior + 1 });
26	    }
27	  }
28	
29	  const nextLiveCells: Cell[] = [];
30	  for (const [key, { cell, count }] of neighborCounts) {
31	    if (willBeAlive(alive.has(key), count)) nextLiveCells.push(cell);
32	  }
33	  return nextLiveCells;
34	}
35

1	import { describe, it, expect } from "vitest";
2	import { nextGeneration } from "./game-of-life.js";
3	
4	describe("Game of Life - Next Generation", () => {
5	  it("empty grid stays empty — [] → []", () => {
6	    expect(nextGeneration([])).toEqual([]);
7	  });
8	  it("single live cell dies from underpopulation — [(0,0)] → []", () => {
9	    expect(nextGeneration([[0, 0]])).toEqual([]);
10	  });
11	  it("two adjacent cells both die from underpopulation — [(0,1), (1,1)] → []", () => {
12	    expect(nextGeneration([[0, 1], [1, 1]])).toEqual([]);
13	  });
14	  it("block still life remains unchanged — [(0,0), (1,0), (0,1), (1,1)] → same", () => {
15	    const block: [number, number][] = [[0, 0], [1, 0], [0, 1], [1, 1]];
16	    const result = nextGeneration(block);
17	    expect(result).toHaveLength(4);
18	    expect(result).toEqual(expect.arrayContaining(block));
19	  });
20	  it("live cell with 2 neighbors survives — center of row survives when it has 2 live neighbors", () => {
21	    // Row of 3: [(0,0), (1,0), (2,0)]. Only center (1,0) has 2 neighbors and survives.
22	    // Also, (1,-1) and (1,1) each have 3 neighbors → born. Verify center is in result.
23	    const result = nextGeneration([[0, 0], [1, 0], [2, 0]]);
24	    expect(result).toEqual(expect.arrayContaining<[number, number]>([[1, 0]]));
25	  });
26	  it("live cell with 3 neighbors survives (Rule 2 example) — center cell (1,1) with 3 live neighbors survives", () => {
27	    // L-shape: (0,0), (1,0), (0,1), (1,1) is a block (2x2). Remove one to make an L:
28	    // Cells: (0,0), (1,0), (0,1). (0,0) has 2 live neighbors and survives. Let's instead check
29	    // that (1,1) — dead in this shape — becomes alive (3 neighbors) AND (0,0),(1,0),(0,1) survive.
30	    const result = nextGeneration([[0, 0], [1, 0], [0, 1]]);
31	    expect(result).toEqual(
32	      expect.arrayContaining<[number, number]>([[0, 0], [1, 0], [0, 1], [1, 1]]),
33	    );
34	    expect(result).toHaveLength(4);
35	  });
36	  it("live cell with more than 3 neighbors dies from overpopulation — center cell (1,1) with 4 neighbors dies", () => {
37	    // Rule 3 example: 3x3 filled minus corners of middle row — actually spec uses full 3x3
38	    // with center: ###/.#./### (8 neighbors of center all live). Center dies from overpopulation.
39	    const cells: [number, number][] = [
40	      [0, 0], [1, 0], [2, 0],
41	      [0, 1], [1, 1], [2, 1],
42	      [0, 2], [1, 2], [2, 2],
43	    ];
44	    const result = nextGeneration(cells);
45	    expect(result).not.toContainEqual([1, 1]);
46	  });
47	  it("dead cell with exactly 3 live neighbors becomes alive (Rule 4 reproduction) — (1,1) becomes alive", () => {
48	    // Rule 4 spec example: L-shape ##./#../...  → gen1 includes (1,1) born from 3 neighbors
49	    const result = nextGeneration([[0, 0], [1, 0], [0, 1]]);
50	    expect(result).toContainEqual([1, 1]);
51	  });
52	  it("blinker oscillates vertical → horizontal — [(0,0), (0,1), (0,2)] → [(-1,1), (0,1), (1,1)]", () => {
53	    const result = nextGeneration([[0, 0], [0, 1], [0, 2]]);
54	    expect(result).toHaveLength(3);
55	    expect(result).toEqual(
56	      expect.arrayContaining<[number, number]>([[-1, 1], [0, 1], [1, 1]]),
57	    );
58	  });
59	  it("handles negative coordinates — pattern with negative x,y transitions correctly", () => {
60	    // Block still life at all-negative coordinates should stay unchanged.
61	    const block: [number, number][] = [[-5, -5], [-4, -5], [-5, -4], [-4, -4]];
62	    const result = nextGeneration(block);
63	    expect(result).toHaveLength(4);
64	    expect(result).toEqual(expect.arrayContaining(block));
65	  });
66	});
