  const alive = new Set(liveCells.map(cellKey));
  const neighborCounts = new Map<string, { cell: Cell; count: number }>();

  for (const cell of liveCells) {
    for (const neighbor of neighborsOf(cell)) {
      const key = cellKey(neighbor);
      const prior = neighborCounts.get(key)?.count ?? 0;
      neighborCounts.set(key, { cell: neighbor, count: prior + 1 });
    }
  }

  const nextLiveCells: Cell[] = [];
  for (const [key, { cell, count }] of neighborCounts) {
    if (willBeAlive(alive.has(key), count)) nextLiveCells.push(cell);
  }
  return nextLiveCells;
}

